var n=`1095-kuy-teav`;var t=`world-1095`;var s=`KH`;var r=`southeast-asia`;var a=4;var o=66;var l={en:`Kuy Teav`,ua:`Куй тієв`};var m={en:`Kuy Teav is a dish from Cambodia prepared with pork bones, garlic, ground pork, shrimp. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Куй тієв, страва кухні країни Камбоджа, яку готують із таких продуктів: свинячі кістки, часник, свинячий фарш, креветка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 45 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 45 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:45,i:[[`pork-bones`,850,`g`],[`water`,1650,`ml`],[`garlic`,4,`clove`],[`star-anise`,2,`pcs`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 10 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 10 хвилин до готовності й м’якості.`,t:[`poaching`],m:10,i:[[`ground-pork`,260,`g`],[`shrimp`,200,`g`]]},{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`rice-noodles`,420,`g`],[`water`,1e3,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`bean-sprouts`,180,`g`],[`green-onion`,35,`g`],[`cilantro`,25,`g`]]}];var u={slug:n,id:t,country:`KH`,region:r,servings:4,minutes:66,title:l,text:m,steps:g};export{s as country,u as default,t as id,o as minutes,r as region,a as servings,n as slug,g as steps,m as text,l as title};